gate = smoothstep(-0.2, 1.0, fbm(4, 4, 2.7, 3))
@crack = (1 - smoothstep(0.3, 1.4, @pattern_edge)) * gate * smoothstep(-0.5, 0.8, fbm(32, 32, 4.4, 2))
